    27	@Service
    28	public class CheckoutService {
    29	    private final ProductRepository productRepository;
    30	    private final OrderRepository orderRepository;
    31	    private final Map<String, CouponStrategy> coupons;
    32	    private final Map<String, ShippingStrategy> shippingMethods;
    33	    private final Map<String, PaymentStrategy> paymentMethods;
    34	    private final Map<String, ClubTierStrategy> clubTiers;
    35	
    36	    public CheckoutService(
    37	            ProductRepository productRepository,
    38	            OrderRepository orderRepository,
    39	            List<CouponStrategy> couponList,
    40	            List<ShippingStrategy> shippingList,
    41	            List<PaymentStrategy> paymentList,
    42	            List<ClubTierStrategy> clubList) {
    43	        this.productRepository = productRepository;
    44	        this.orderRepository = orderRepository;
    45	        this.coupons = couponList.stream().collect(Collectors.toMap(CouponStrategy::getCode, c -> c));
    46	        this.shippingMethods = shippingList.stream().collect(Collectors.toMap(ShippingStrategy::getCode, s -> s));
    47	        this.paymentMethods = paymentList.stream().collect(Collectors.toMap(PaymentStrategy::getCode, p -> p));
    48	        this.clubTiers = clubList.stream().collect(Collectors.toMap(ClubTierStrategy::getCode, t -> t));
    49	    }
    50	
    51	    @Transactional(readOnly = true)
    52	    public SummaryResponse calculateSummary(CheckoutRequest request) {
    53	        validateRequest(request);
    54	
    55	        Map<String, Product> productMap = loadProducts(request);
    56	
    57	        BigDecimal productsSubtotal = calculateProductsSubtotal(request, productMap);
    58	        BigDecimal totalWeightKg = calculateTotalWeight(request, productMap);
    59	
    60	        ShippingResult shippingResult = calculateShipping(request, totalWeightKg);
    61	
    62	        ClubTierStrategy clubTier = getClubTier(request.getClubTier());
    63	        ClubBenefits clubBenefits = clubTier.getBenefits(request, productsSubtotal);
    64	
    65	        BigDecimal shippingCost = clubBenefits.isFreeShipping() ? BigDecimal.ZERO : shippingResult.getCost();
    66	        int deliveryDays = shippingResult.getDeliveryDays();
    67	
    68	        BigDecimal couponDiscount = calculateCouponDiscount(request, productMap, productsSubtotal, shippingCost);
    69	
    70	        BigDecimal insurance = calculateInsurance(request, productsSubtotal);
    71	
    72	        BigDecimal orderTotal = productsSubtotal
    73	            .subtract(couponDiscount)
    74	            .add(shippingCost)
    75	            .add(insurance);
    76	
    77	        PaymentResult paymentResult = calculatePayment(request, orderTotal);
    78	
    79	        BigDecimal credit = MoneyRounding.round(
    80	            productsSubtotal.multiply(clubBenefits.getCreditPercentage())
    81	        );
    82	
    83	        boolean gift = clubBenefits.getGiftThreshold() != null &&
    84	                      productsSubtotal.compareTo(clubBenefits.getGiftThreshold()) > 0;
    85	
    86	        SummaryResponse summary = new SummaryResponse();
    87	        summary.setProductsSubtotal(productsSubtotal);
    88	        summary.setCouponDiscount(couponDiscount);
    89	        summary.setShippingCost(shippingCost);
    90	        summary.setDeliveryDays(deliveryDays);
    91	        summary.setInsurance(insurance);
    92	        summary.setPaymentAdjustment(paymentResult.getAdjustment());
    93	        summary.setFinalTotal(paymentResult.getFinalTotal());
    94	        summary.setInstallments(paymentResult.getInstallments());
    95	        summary.setInstallmentAmount(paymentResult.getInstallmentAmount());
    96	        summary.setNextPurchaseCredit(credit);
    97	        summary.setGift(gift);
    98	
    99	        return summary;
   100	    }
   101	
   102	    private void validateRequest(CheckoutRequest request) {
   103	        if (request.getCustomer() == null || request.getCustomer().getCpf() == null ||
   104	            request.getCustomer().getEmail() == null) {
   105	            throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
   106	        }
   107	
   108	        if (request.getItems() == null || request.getItems().isEmpty()) {
   109	            throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
   110	        }
   111	
   112	        Map<String, Long> skuCount = request.getItems().stream()
   113	            .collect(Collectors.groupingBy(item -> item.getSku(), Collectors.counting()));
   114	
   115	        for (var item : request.getItems()) {
   116	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
   117	                throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
   118	            }
   119	            if (skuCount.get(item.getSku()) > 1) {
   120	                throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
   121	            }
   122	        }
   123	    }
   124	
   125	    private Map<String, Product> loadProducts(CheckoutRequest request) {
   126	        List<String> skus = request.getItems().stream()
   127	            .map(item -> item.getSku())
   128	            .collect(Collectors.toList());
   129	
   130	        List<Product> products = productRepository.findAllById(skus);
   131	
   132	        if (products.size() != skus.size()) {
   133	            throw new OrderException("UNKNOWN_PRODUCT", HttpStatus.UNPROCESSABLE_ENTITY);
   134	        }
   135	
   136	        Map<String, Product> productMap = new HashMap<>();
   137	        for (Product product : products) {
   138	            productMap.put(product.getSku(), product);
   139	
   140	            if (product.getDiscontinued()) {
   141	                throw new OrderException("PRODUCT_DISCONTINUED", HttpStatus.UNPROCESSABLE_ENTITY);
   142	            }
   143	
   144	            int requestedQty = request.getItems().stream()
   145	                .filter(item -> item.getSku().equals(product.getSku()))
   146	                .findFirst()
   147	                .get()
   148	                .getQuantity();
   149	
   150	            if (product.getStock() < requestedQty) {
   151	                throw new OrderException("INSUFFICIENT_STOCK", HttpStatus.UNPROCESSABLE_ENTITY);
   152	            }
   153	        }
   154	
   155	        return productMap;
   156	    }
   157	
   158	    private BigDecimal calculateProductsSubtotal(CheckoutRequest request, Map<String, Product> products) {
   159	        BigDecimal subtotal = BigDecimal.ZERO;
   160	        for (var item : request.getItems()) {
   161	            Product product = products.get(item.getSku());
   162	            subtotal = subtotal.add(product.getPrice().multiply(new BigDecimal(item.getQuantity())));
   163	        }
   164	        return MoneyRounding.round(subtotal);
   165	    }
   166	
   167	    private BigDecimal calculateTotalWeight(CheckoutRequest request, Map<String, Product> products) {
   168	        BigDecimal weight = BigDecimal.ZERO;
   169	        for (var item : request.getItems()) {
   170	            Product product = products.get(item.getSku());
   171	            weight = weight.add(product.getWeightKg().multiply(new BigDecimal(item.getQuantity())));
   172	        }
   173	        return weight;
   174	    }
   175	
   176	    private ShippingResult calculateShipping(CheckoutRequest request, BigDecimal totalWeightKg) {
   177	        if (request.getClubTier() == null || !clubTiers.containsKey(request.getClubTier())) {
   178	            throw new OrderException("INVALID_CLUB_TIER", HttpStatus.UNPROCESSABLE_ENTITY);
   179	        }
   180	
   181	        if (request.getRegion() == null) {
   182	            throw new OrderException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
   183	        }
   184	
   185	        if (!List.of("SOUTHEAST", "SOUTH", "MIDWEST", "NORTH", "NORTHEAST").contains(request.getRegion())) {
   186	            throw new OrderException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
   187	        }
   188	
   189	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
   190	            throw new OrderException("INVALID_ZIP_CODE", HttpStatus.UNPROCESSABLE_ENTITY);
   191	        }
   192	
   193	        if (request.getShippingMethod() == null || !shippingMethods.containsKey(request.getShippingMethod())) {
   194	            throw new OrderException("INVALID_SHIPPING_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
   195	        }
   196	
   197	        ShippingStrategy shipping = shippingMethods.get(request.getShippingMethod());
   198	
   199	        if (!shipping.isAvailable(request, totalWeightKg)) {
   200	            if (request.getShippingMethod().equals("ECONOMY") || request.getShippingMethod().equals("EXPRESS")) {
   201	                throw new OrderException("CARRIER_UNAVAILABLE", HttpStatus.SERVICE_UNAVAILABLE);
   202	            }
   203	            throw new OrderException("SHIPPING_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
   204	        }
   205	
   206	        try {
   207	            return shipping.calculate(request, totalWeightKg);
   208	        } catch (Exception e) {
   209	            throw new OrderException("CARRIER_UNAVAILABLE", HttpStatus.SERVICE_UNAVAILABLE);
   210	        }
   211	    }
   212	
   213	    private BigDecimal calculateCouponDiscount(CheckoutRequest request, Map<String, Product> products,
   214	                                                BigDecimal productsSubtotal, BigDecimal shippingCost) {
   215	        if (request.getCoupon() == null) {
   216	            return BigDecimal.ZERO;
   217	        }
   218	
   219	        if (!coupons.containsKey(request.getCoupon())) {
   220	            throw new OrderException("INVALID_COUPON", HttpStatus.UNPROCESSABLE_ENTITY);
   221	        }
   222	
   223	        CouponStrategy coupon = coupons.get(request.getCoupon());
   224	
   225	        List<String> customerStatuses = orderRepository
   226	            .findByCustomerCpfAndStatusIn(request.getCustomer().getCpf(),
   227	                                         List.of("PAID", "SHIPPED", "DELIVERED"))
   228	            .stream()
   229	            .map(Order::getStatus)
   230	            .collect(Collectors.toList());
   231	
   232	        if (!coupon.isApplicable(request, customerStatuses)) {
   233	            throw new OrderException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
   234	        }
   235	
   236	        BigDecimal discount = coupon.calculateDiscount(request, products, productsSubtotal, shippingCost);
   237	
   238	        if (request.getCoupon().equals("MINUS50")) {
   239	            if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) {
   240	                throw new OrderException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
   241	            }
   242	        }
   243	
   244	        BigDecimal maxDiscount = MoneyRounding.round(productsSubtotal.multiply(new BigDecimal("0.30")));
   245	        if (discount.compareTo(maxDiscount) > 0) {
   246	            discount = maxDiscount;
   247	        }
   248	
   249	        return discount;
   250	    }
   251	
   252	    private BigDecimal calculateInsurance(CheckoutRequest request, BigDecimal productsSubtotal) {
   253	        BigDecimal percentage;
   254	        BigDecimal limit = null;
   255	
   256	        switch (request.getRegion()) {
   257	            case "SOUTHEAST", "SOUTH" -> percentage = new BigDecimal("0.01");
   258	            case "MIDWEST" -> percentage = new BigDecimal("0.015");
   259	            case "NORTH" -> {
   260	                percentage = new BigDecimal("0.025");
   261	                limit = new BigDecimal("30.00");
   262	            }
   263	            case "NORTHEAST" -> {
   264	                percentage = new BigDecimal("0.02");
   265	                limit = new BigDecimal("30.00");
   266	            }
   267	            default -> throw new OrderException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
   268	        }
   269	
   270	        BigDecimal insurance = MoneyRounding.round(productsSubtotal.multiply(percentage));
   271	
   272	        if (limit != null && insurance.compareTo(limit) > 0) {
   273	            insurance = limit;
   274	        }
   275	
   276	        return insurance;
   277	    }
   278	
   279	    private PaymentResult calculatePayment(CheckoutRequest request, BigDecimal orderTotal) {
   280	        if (request.getPaymentMethod() == null || !paymentMethods.containsKey(request.getPaymentMethod())) {
   281	            throw new OrderException("INVALID_PAYMENT_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
   282	        }
   283	
   284	        PaymentStrategy payment = paymentMethods.get(request.getPaymentMethod());
   285	
   286	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
   287	
   288	        if (!payment.isValidInstallments(installments)) {
   289	            throw new OrderException("INVALID_INSTALLMENTS", HttpStatus.UNPROCESSABLE_ENTITY);
   290	        }
   291	
   292	        if (!payment.isAvailable(request, orderTotal)) {
   293	            throw new OrderException("PAYMENT_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
   294	        }
   295	
   296	        boolean hasCoupon = request.getCoupon() != null;
   297	
   298	        return payment.calculate(request, orderTotal, hasCoupon);
   299	    }
   300	
   301	    private ClubTierStrategy getClubTier(String tierCode) {
   302	        if (tierCode == null || !clubTiers.containsKey(tierCode)) {
   303	            throw new OrderException("INVALID_CLUB_TIER", HttpStatus.UNPROCESSABLE_ENTITY);
   304	        }
   305	        return clubTiers.get(tierCode);
   306	    }
