    66	        int deliveryDays = shippingResult.getDeliveryDays();
    67	
    68	        BigDecimal couponDiscount = calculateCouponDiscount(request, productMap, productsSubtotal, shippingCost);
    69	
    70	        BigDecimal insurance = calculateInsurance(request, productsSubtotal);
    71	
    72	        BigDecimal orderTotal = productsSubtotal
    73	            .subtract(couponDiscount)
    74	            .add(shippingCost)
    75	            .add(insurance);
    76	
    77	        PaymentResult paymentResult = calculatePayment(request, orderTotal);
    78	
    79	        BigDecimal credit = MoneyRounding.round(
    80	            productsSubtotal.multiply(clubBenefits.getCreditPercentage())
    81	        );
    82	
    83	        boolean gift = clubBenefits.getGiftThreshold() != null &&
    84	                      productsSubtotal.compareTo(clubBenefits.getGiftThreshold()) > 0;
