   102	    private void validateRequest(CheckoutRequest request) {
   103	        if (request.getCustomer() == null || request.getCustomer().getCpf() == null ||
   104	            request.getCustomer().getEmail() == null) {
   105	            throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
   106	        }
   107	
   108	        if (request.getItems() == null || request.getItems().isEmpty()) {
   109	            throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
   110	        }
   111	
   112	        Map<String, Long> skuCount = request.getItems().stream()
   113	            .collect(Collectors.groupingBy(item -> item.getSku(), Collectors.counting()));
   114	
   115	        for (var item : request.getItems()) {
   116	            if (item.getSku() == null || item.getQuantity() == null || item.getQuantity() <= 0) {
   117	                throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
   118	            }
   119	            if (skuCount.get(item.getSku()) > 1) {
   120	                throw new OrderException("INVALID_ORDER", HttpStatus.UNPROCESSABLE_ENTITY);
   121	            }
   122	        }
   123	    }
   124	
   125	    private Map<String, Product> loadProducts(CheckoutRequest request) {
   126	        List<String> skus = request.getItems().stream()
   127	            .map(item -> item.getSku())
   128	            .collect(Collectors.toList());
   129	
   130	        List<Product> products = productRepository.findAllById(skus);
   131	
   132	        if (products.size() != skus.size()) {
   133	            throw new OrderException("UNKNOWN_PRODUCT", HttpStatus.UNPROCESSABLE_ENTITY);
   134	        }
   135	
   136	        Map<String, Product> productMap = new HashMap<>();
   137	        for (Product product : products) {
   138	            productMap.put(product.getSku(), product);
   139	
   140	            if (product.getDiscontinued()) {
   141	                throw new OrderException("PRODUCT_DISCONTINUED", HttpStatus.UNPROCESSABLE_ENTITY);
   142	            }
   143	
   144	            int requestedQty = request.getItems().stream()
   145	                .filter(item -> item.getSku().equals(product.getSku()))
   146	                .findFirst()
   147	                .get()
   148	                .getQuantity();
   149	
   150	            if (product.getStock() < requestedQty) {
   151	                throw new OrderException("INSUFFICIENT_STOCK", HttpStatus.UNPROCESSABLE_ENTITY);
   152	            }
   153	        }
   154	
   155	        return productMap;
   156	    }
