   167	    private BigDecimal calculateTotalWeight(CheckoutRequest request, Map<String, Product> products) {
   168	        BigDecimal weight = BigDecimal.ZERO;
   169	        for (var item : request.getItems()) {
   170	            Product product = products.get(item.getSku());
   171	            weight = weight.add(product.getWeightKg().multiply(new BigDecimal(item.getQuantity())));
   172	        }
   173	        return weight;
   174	    }
