   176	    private ShippingResult calculateShipping(CheckoutRequest request, BigDecimal totalWeightKg) {
   177	        if (request.getClubTier() == null || !clubTiers.containsKey(request.getClubTier())) {
   178	            throw new OrderException("INVALID_CLUB_TIER", HttpStatus.UNPROCESSABLE_ENTITY);
   179	        }
   180	
   181	        if (request.getRegion() == null) {
   182	            throw new OrderException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
   183	        }
   184	
   185	        if (!List.of("SOUTHEAST", "SOUTH", "MIDWEST", "NORTH", "NORTHEAST").contains(request.getRegion())) {
   186	            throw new OrderException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
   187	        }
   188	
   189	        if (request.getZipCode() == null || !request.getZipCode().matches("\\d{8}")) {
   190	            throw new OrderException("INVALID_ZIP_CODE", HttpStatus.UNPROCESSABLE_ENTITY);
   191	        }
   192	
   193	        if (request.getShippingMethod() == null || !shippingMethods.containsKey(request.getShippingMethod())) {
   194	            throw new OrderException("INVALID_SHIPPING_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
   195	        }
   196	
   197	        ShippingStrategy shipping = shippingMethods.get(request.getShippingMethod());
   198	
   199	        if (!shipping.isAvailable(request, totalWeightKg)) {
   200	            if (request.getShippingMethod().equals("ECONOMY") || request.getShippingMethod().equals("EXPRESS")) {
   201	                throw new OrderException("CARRIER_UNAVAILABLE", HttpStatus.SERVICE_UNAVAILABLE);
   202	            }
   203	            throw new OrderException("SHIPPING_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
   204	        }
   205	
   206	        try {
   207	            return shipping.calculate(request, totalWeightKg);
   208	        } catch (Exception e) {
   209	            throw new OrderException("CARRIER_UNAVAILABLE", HttpStatus.SERVICE_UNAVAILABLE);
   210	        }
   211	    }
   212	
   213	    private BigDecimal calculateCouponDiscount(CheckoutRequest request, Map<String, Product> products,
   214	                                                BigDecimal productsSubtotal, BigDecimal shippingCost) {
   215	        if (request.getCoupon() == null) {
   216	            return BigDecimal.ZERO;
   217	        }
   218	
   219	        if (!coupons.containsKey(request.getCoupon())) {
   220	            throw new OrderException("INVALID_COUPON", HttpStatus.UNPROCESSABLE_ENTITY);
   221	        }
   222	
   223	        CouponStrategy coupon = coupons.get(request.getCoupon());
   224	
   225	        List<String> customerStatuses = orderRepository
   226	            .findByCustomerCpfAndStatusIn(request.getCustomer().getCpf(),
   227	                                         List.of("PAID", "SHIPPED", "DELIVERED"))
   228	            .stream()
   229	            .map(Order::getStatus)
   230	            .collect(Collectors.toList());
   231	
   232	        if (!coupon.isApplicable(request, customerStatuses)) {
   233	            throw new OrderException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
   234	        }
   235	
   236	        BigDecimal discount = coupon.calculateDiscount(request, products, productsSubtotal, shippingCost);
   237	
   238	        if (request.getCoupon().equals("MINUS50")) {
   239	            if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) {
   240	                throw new OrderException("COUPON_NOT_APPLICABLE", HttpStatus.UNPROCESSABLE_ENTITY);
   241	            }
   242	        }
   243	
   244	        BigDecimal maxDiscount = MoneyRounding.round(productsSubtotal.multiply(new BigDecimal("0.30")));
   245	        if (discount.compareTo(maxDiscount) > 0) {
   246	            discount = maxDiscount;
   247	        }
   248	
   249	        return discount;
   250	    }
   251	
   252	    private BigDecimal calculateInsurance(CheckoutRequest request, BigDecimal productsSubtotal) {
   253	        BigDecimal percentage;
   254	        BigDecimal limit = null;
   255	
   256	        switch (request.getRegion()) {
   257	            case "SOUTHEAST", "SOUTH" -> percentage = new BigDecimal("0.01");
   258	            case "MIDWEST" -> percentage = new BigDecimal("0.015");
   259	            case "NORTH" -> {
   260	                percentage = new BigDecimal("0.025");
   261	                limit = new BigDecimal("30.00");
   262	            }
   263	            case "NORTHEAST" -> {
   264	                percentage = new BigDecimal("0.02");
   265	                limit = new BigDecimal("30.00");
   266	            }
   267	            default -> throw new OrderException("INVALID_REGION", HttpStatus.UNPROCESSABLE_ENTITY);
   268	        }
   269	
   270	        BigDecimal insurance = MoneyRounding.round(productsSubtotal.multiply(percentage));
   271	
   272	        if (limit != null && insurance.compareTo(limit) > 0) {
   273	            insurance = limit;
   274	        }
   275	
   276	        return insurance;
   277	    }
   278	
   279	    private PaymentResult calculatePayment(CheckoutRequest request, BigDecimal orderTotal) {
   280	        if (request.getPaymentMethod() == null || !paymentMethods.containsKey(request.getPaymentMethod())) {
   281	            throw new OrderException("INVALID_PAYMENT_METHOD", HttpStatus.UNPROCESSABLE_ENTITY);
   282	        }
   283	
   284	        PaymentStrategy payment = paymentMethods.get(request.getPaymentMethod());
   285	
   286	        int installments = request.getInstallments() != null ? request.getInstallments() : 1;
   287	
   288	        if (!payment.isValidInstallments(installments)) {
   289	            throw new OrderException("INVALID_INSTALLMENTS", HttpStatus.UNPROCESSABLE_ENTITY);
   290	        }
   291	
   292	        if (!payment.isAvailable(request, orderTotal)) {
   293	            throw new OrderException("PAYMENT_METHOD_UNAVAILABLE", HttpStatus.UNPROCESSABLE_ENTITY);
   294	        }
   295	
   296	        boolean hasCoupon = request.getCoupon() != null;
   297	
   298	        return payment.calculate(request, orderTotal, hasCoupon);
   299	    }
