   301	    private ClubTierStrategy getClubTier(String tierCode) {
   302	        if (tierCode == null || !clubTiers.containsKey(tierCode)) {
   303	            throw new OrderException("INVALID_CLUB_TIER", HttpStatus.UNPROCESSABLE_ENTITY);
   304	        }
   305	        return clubTiers.get(tierCode);
