    15	        return "AWAITING_PAYMENT";
    16	    }
    17	
    18	    @Override
    19	    public void handlePayment(Order order, PaymentRequest paymentRequest, OrderStateContext context) {
    20	        OrderPayment existingPayment = context.findPaymentByOrderId(order.getId());
    21	        if (existingPayment != null) {
    22	            if (existingPayment.getTransactionId().equals(paymentRequest.getTransactionId())) {
    23	                return;
    24	            }
    25	            throw new OrderException("OPERATION_NOT_ALLOWED", HttpStatus.CONFLICT);
    26	        }
    27	
    28	        if (context.isPaymentExpired(order, paymentRequest)) {
    29	            order.setStatus("CANCELLED");
    30	            order.setState(new CancelledState());
    31	            context.saveOrder(order);
    32	            context.notifyCustomer(order.getCustomerCpf(), "ORDER_CANCELLED", order.getId());
    33	            throw new OrderException("ORDER_EXPIRED", HttpStatus.CONFLICT);
    34	        }
    35	
    36	        if (!context.hasStockForOrder(order)) {
    37	            order.setStatus("CANCELLED");
    38	            order.setState(new CancelledState());
    39	            context.saveOrder(order);
    40	            context.notifyCustomer(order.getCustomerCpf(), "ORDER_CANCELLED", order.getId());
    41	            throw new OrderException("INSUFFICIENT_STOCK", HttpStatus.CONFLICT);
    42	        }
    43	
    44	        context.savePayment(new OrderPayment(order.getId(), paymentRequest.getTransactionId(), paymentRequest.getPaidAt()));
    45	
    46	        context.reserveStock(order);
    47	        context.addCredit(order.getCustomerCpf(), order.getNextPurchaseCredit());
    48	        context.notifyCustomer(order.getCustomerCpf(), "PAYMENT_APPROVED", order.getId());
    49	
    50	        order.setStatus("PAID");
